document.addEventListener("DOMContentLoaded",function(){const t=document.querySelector(".hamburger"),r=document.querySelector(".nav-menu");t&&r&&(t.addEventListener("click",function(){r.classList.toggle("active"),t.classList.toggle("active")}),document.querySelectorAll(".nav-menu a").forEach(e=>{e.addEventListener("click",()=>{r.classList.remove("active"),t.classList.remove("active")})}));const o=document.querySelectorAll(".reveal"),s=new IntersectionObserver(e=>{e.forEach(c=>{c.isIntersecting&&c.target.classList.add("active")})},{threshold:.1});o.forEach(e=>{s.observe(e)}),document.querySelectorAll('a[href^="#"]').forEach(e=>{e.addEventListener("click",function(c){c.preventDefault();const n=document.querySelector(this.getAttribute("href"));n&&n.scrollIntoView({behavior:"smooth",block:"start"})})})});
